sections.code:
variable "env" {
  type = string
}

resource "aws_s3_bucket" "logs" {
  bucket = "acme-logs-${var.env}"
}

output "bucket_arn" {
  value = aws_s3_bucket.logs.arn
}

terraform {
  backend "s3" {
    bucket       = "acme-tfstate"
    key          = "prod/reseau.tfstate"
    region       = "eu-west-3"
    use_lockfile = true
  }
}

questions.code:
variable "utilisateurs" {
  default = ["ana", "leo", "mia"]
}

resource "aws_iam_user" "u" {
  count = length(var.utilisateurs)
  name  = var.utilisateurs[count.index]
}
